type OrderState = "created" | "paid" | "shipped";

function assertNever(value: never): never {
	throw new Error(`unexpected state: ${String(value)}`);
}

function label(state: OrderState): string {
	switch (state) {
		case "created":
			return "Created";
		case "paid":
			return "Paid";
		case "shipped":
			return "Shipped";
		default:
			return assertNever(state);
	}
}

